window.QUESTIONS.push(...[{"id":"112-5-A-26","exam":"112-5","q":26,"unit":"經濟學","topic":"經濟學","stem":"經濟日報(2023.10.30)：「中央銀行在大選後會重啟升息嗎？國內專家看法兩極。國泰世華銀行首席經濟\n學家林啟超分析，油價反彈、新臺幣匯率貶值使進口通膨升溫，央行確實有升息機會；台經院景氣預測\n中心主任孫明德則說，除非油電平穩機制落幕，否則 113 年首季升息的機率不大。」根據上述報導，下\n列敘述何者正確？","options":["大選過後，央行是否升息，屬於實證經濟學與總體經濟學的範疇","央行調整利率來影響經濟狀況，為價格機能的展現","凱因斯主張，若經濟景氣低迷，應調降利率以刺激景氣回升","以升息對抗通貨膨脹，屬於貨幣政策"],"answer":"D","official":"(A) 央行是否升息屬於規範經濟學與總體經濟學\n(B) 央行調整利率屬於總體經濟政策\n(C) 凱因斯主張以財政政策刺激景氣回升"},{"id":"112-5-A-27","exam":"112-5","q":27,"unit":"經濟學","topic":"經濟學","stem":"承上題，假設其他條件不變，下列敘述何者正確？","options":["若中央銀行重啟升息，將使債券價格水漲船高","若中央銀行重啟升息，則土地價格將隨之上漲","臺幣貶值使進口通膨升溫，屬於輸入型物價膨脹","油價反彈導致通貨膨脹升溫，屬於需求拉動型物價膨脹"],"answer":"C","official":"(A) 債券價格 ＝ 債息收入\n利率 →央行升息(利率  )將使債\n券價格下跌\n(B) 地價 ＝ 地租\n利率 →央行升息(利率  )將使地價下跌\n(D) 油價反彈所造成的物價膨脹，屬於成本推動型或\n輸入型物價膨脹"},{"id":"112-5-A-28","exam":"112-5","q":28,"unit":"經濟學","topic":"經濟學","stem":"下列有底線的敘述，何者屬於點的移動？\n①咖啡價格上漲導致\\u{消費者少喝咖啡}\n②利率上漲導致\\u{投資量減少}\n③麵粉價格上漲導致\\u{麵包量減少}\n④少子化日益嚴重導致\\u{大學紛紛退場}","options":["①②", "①④", "②③", "③④"],"answer":"A","official":"③④導致數量變動的因素均非財貨本身價格所引\n起，因此均為線的移動"},{"id":"112-5-A-29","exam":"112-5","q":29,"unit":"經濟學","topic":"經濟學","stem":"若 X 為正常財，其市場需求函數與供給函數分別為 Q=120−3P 與 Q=20+2P。下列何者正確？","options":["市場的均衡價格為 60 元，均衡交易量為 20 單位", "若政府設定價格下限為 30 元，市場將發生超額供給", "在市場達成均衡時，需求富於彈性，因此廠商可降低價格以增加收入", "若預期未來價格將上漲，則供給會增加，需求會減少"],"answer":"B","official":"(A) 均衡時，120 − 3P ＝ 20 ＋ 2P P* ＝ 20，Q* ＝ 60\n(C) 均衡點為需求線的中點，需求彈性 ＝ 1，廠商總收\n入到達最大，因此廠商無法調整價格以增加總收入\n(D) 預期未來價格上漲，將導致需求增加，供給減少","scan":"data:image/webp;base64,"},{"id":"112-5-A-30","exam":"112-5","q":30,"unit":"經濟學","topic":"經濟學","stem":"某消費者消費 X 財貨的總效用函數為 TU_{X}=−3Q^{2}+60Q，邊際效用函數為 MU_{X}=−6Q+60，且貨幣邊際效用 MU_{m}=3。試問下列敘述何者\\u{錯誤}？","options":["若無預算限制，也不考慮 X 財貨價格，則消費者的最適消費量為 10", "若 X 財貨的價格為 10 元，則消費者的需求量為 10", "消費量為 6 時，X 財貨的價格為 8 元", "消費量為 6 時，總效用為 252"],"answer":"B","official":"(A) 總效用到達最大時\nMUX ＝ −＋＝ 6Q 60 0  Q ＝ 10\n(B)  P 10 X ＝\nMU 3 m ＝ X\nX\nm\nMU P\nMU\n＝\nMUX 10\n3\n＝ ＝ MU 30 X 代\n入 MU 6Q 60 X ＝ −＋  ＝− ＋ 30 6Q 60 ＝ Q5\n(C) 消費量為 6 時\nMUX ＝ −× ＋ ＝ 6 6 60 24\nX 財貨的價格 X\nX\nm\nMU P\nMU ＝ 24 83 ＝＝\n(D) 消費量為 6 時， TUX\n2 ＝− × ＋ × ＝ 3 6 60 6 252","scan":"data:image/webp;base64,"},{"id":"112-5-A-31","exam":"112-5","q":31,"unit":"經濟學","topic":"經濟學","stem":"假設其他條件不變，下列敘述何者錯誤？","options":["機會成本遞增法則是指，每增加一單位財貨的生產，其機會成本會隨著產量的增加而遞增","邊際效用遞減法則是指，每增加一單位財貨的消費，其邊際效用會隨著消費量的增加而遞減","根據價值的矛盾，財貨價格的高低決定於其邊際效用的大小","根據節儉的矛盾，在充分就業的社會中，自發性儲蓄的增加將導致國民所得減少"],"answer":"D","official":"(D) 節儉的矛盾是發生在未達充分就業的社會中"},{"id":"112-5-A-32","exam":"112-5","q":32,"unit":"經濟學","topic":"經濟學","stem":"假設要素市場(L)與產品市場(X)均為完全競爭，且廠商的短期生產函數為總產量 TP=−L^{3}+12L^{2}，邊際產量 MP=−3L^{2}+24L，若廠商的勞動雇用量為 6 人，且產品價格為 10 元，則勞動的工資率為何？","options":["120 元", "240 元", "360 元", "480 元"],"answer":"C","official":"X 商品為完全競爭， MR P XX ＝ ＝10 ，工資率 PL 由\nP MRP LL ＝ 決定\nMRP MR MP L XL ＝ × ，將 L ＝ 6 代入 2 MP 3L 24L L ＝− ＋\n中 MP 36 L ＝ ， MRPL ＝× ＝ 10 36 360 ＝ P 360 L","scan":"data:image/webp;base64,"},{"id":"112-5-A-33","exam":"112-5","q":33,"unit":"經濟學","topic":"經濟學","stem":"承上題，下列敘述何者錯誤？","options":["廠商的勞動雇用量為 6 人時，MP 處於遞增階段","廠商合理的生產階段時，平均產量最小值為 32","廠商合理的生產階段時，最大勞動雇用量應為 8 人","廠商總產量最大值為 256 單位"],"answer":"A","official":"32 TP L 12L ＝ −＋ ，MP 2 ＝− ＋ 3L 24L\n AP ＝ TP L÷ 2 ＝ −＋ L 12L\nAP ＝ MP，AP 最大  22 − ＋ ＝− ＋  L 12L 3L 24L L ＝ 6\nMP ＝ 0，TP 最大  2 −3L 24L 0 ＋＝  L ＝ 8\n(A) L ＝ 6 時，為 AP 最高點，MP 遞減\n(B) 廠商合理的生產階段時，平均產量最小值發生在\nMP ＝ 0 處  AP 2 ＝ − ＋ ×＝ 8 12 8 32\n(C) 合理的生產階段介於 AP ＝ MP 到 MP ＝ 0 之間→合\n理的勞動雇用量為 6L8 ≦≦\n(D) 廠商總產量最大值\nMP ＝ 0 L ＝ 8 TP 32 ＝− ＋ × ＝ 8 12 8 256"},{"id":"112-5-A-34","exam":"112-5","q":34,"unit":"經濟學","topic":"經濟學","stem":"有關成本的敘述，下列何者正確？","options":["廠商繼續從事經營的基本條件，是賺取到相當於內含成本的經濟利潤","固定成本是廠商支付給固定要素的成本，因此購買機器設備的支出屬於固定成本","長期平均成本線受邊際報酬遞減法則的影響，呈現 U 字形","因地緣政治的不確定性導致廠商經營成本上升，將使長期平均成本線整條向上移動"],"answer":"D","official":"(A) 廠商繼續從事經營的基本條件，是賺取到相當於\n內含成本的會計利潤\n(B) 購買機器設備的支出並非成本，機器設備的折舊\n才是成本\n(C) 長期平均成本線受規模報酬遞增與遞減的影響，\n呈現 U 字形"},{"id":"112-5-A-35","exam":"112-5","q":35,"unit":"經濟學","topic":"經濟學","stem":"已知某廠商的總固定成本為 100，其產量與短期成本如表(一)所示，則廠商達到最低平均成本的產量應\n為多少？\n表(一)\nQ 1 2 3 4 5 6\nTVC 40 80 140 320 640 1280","options":["2","3","4","5"],"answer":"B","official":"如下表所示，平均成本最低值 ＝ 80 時，所對應的產量\n→Q ＝ 3\nQ 1 2 3 4 5 6\nTVC 40 80 140 320 640 1280\nTC 140 180 240 420 740 1380\nAC 140 90 80 105 148 230","scan":"data:image/webp;base64,"},{"id":"112-5-A-36","exam":"112-5","q":36,"unit":"經濟學","topic":"經濟學","stem":"已知某完全競爭廠商的均衡價格為 50 元，平均成本為 40，平均固定成本為 10，超額利潤為 4000，短期停業點的產量為均衡產量的一半，則下列敘述何者\\u{錯誤}？","options":["廠商的總收益函數為 TR=50Q", "廠商的總固定成本為 4000", "廠商短期停業點的產量為 200 單位", "廠商短期停業時的總變動成本為均衡時總變動成本的一半"],"answer":"D","official":"π ＝− TR TC ＝− Q AR ( AC)\n 4000 Q 50 40 ＝− () ＝ Q* 400\n(A) TR P Q 50Q ＝× ＝\n(B) TFC AFC Q ＝× ＝× ＝ 10 400 4000\n(C) 短期停業點的產量 ＝均衡產量的一半 ＝ 200\n(D) 短期停業時的 TVC ＝ 0\n均衡時的 TVC ＝− TC TFC ＝− Q AC AFC ()\n＝− 400 4( 0 10) ＝ 12000","scan":"data:image/webp;base64,"},{"id":"112-5-A-37","exam":"112-5","q":37,"unit":"經濟學","topic":"經濟學","stem":"有關獨占廠商的敘述，下列何者正確？","options":["因為獨占廠商沒有供給線，因此沒有最大利潤的均衡點","因為獨占廠商有能力採取差別取價，因此不存在消費者剩餘","獨占廠商達成長期均衡時，不會發生虧損","獨占廠商面對供給彈性愈小的市場，訂價愈高"],"answer":"C","official":"(A) 獨占廠商最大利潤的均衡點為 MR ＝ MC，與是否\n存在供給線無關\n(B) 只有第一級差別取價時不存在消費者剩餘\n(D) 需求彈性愈小，訂價愈高"},{"id":"112-5-A-38","exam":"112-5","q":38,"unit":"經濟學","topic":"經濟學","stem":"下列敘述何者正確？","options":["所有市場結構的廠商都是以 MR＝MC 決定最適生產量", "為了追求最大利潤，獨占廠商會在需求彈性小於 1 的階段，以提高價格的方式從事生產", "獨占性競爭廠商因為面對眾多的競爭者，因此創新行為最多", "寡占廠商因為面對拗折的需求線，因此經常進行價格競爭"],"answer":"A","official":"(B) 追求利潤最大的獨占廠商不會在需求彈性小於 1\n的階段生產\n(C) 獨占性競爭廠商因為長期無超額利潤，因此缺乏\n創新動力\n(D) 寡占廠商面對拗折需求線使其產品價格具有僵\n固性","scan":"data:image/webp;base64,"},{"id":"112-5-A-39","exam":"112-5","q":39,"unit":"經濟學","topic":"經濟學","stem":"以下為理財鴿網站根據主計總處發布數據的報導(2023.08.19)：「若將臺灣家庭每戶可支配所得高低分為\n5 組，2022 年最高 20%的家庭每戶所得年增率 1.8%，最低 20%的家庭每戶所得年增率也是 1.8%。\n2022 年臺灣各級政府對家庭提供各項補助，使最高與最低家庭 5 等分位所得差距由政府移轉之前的 7.50\n倍，降到 6.15 倍。」根據上述報導，下列敘述何者正確？","options":["因為最高所得組與最低所得組的年增率相同，因此最高最低所得倍數＝1", "因為最高所得組與最低所得組的年增率相同，因此吉尼係數＝1", "相較於政府補助前，政府補助後的洛侖士曲線較靠近對角線", "相較於政府補助前，政府補助後的吉尼係數較接近 1"],"answer":"C","official":"(A) 最高最低所得倍數是以家戶平均所得計算，而非\n以所得的年增率計算\n(B) 吉尼係數 ＝ 1 表示所得分配絕對不平均，而非所得\n年增率相同\n(D) 政府補助使所得分配趨於平均，將使吉尼係數變\n小而愈靠近 0","scan":"data:image/webp;base64,"},{"id":"112-5-A-40","exam":"112-5","q":40,"unit":"經濟學","topic":"經濟學","stem":"承上題，若因政府補助而使家戶單位的可支配所得增加，根據簡單凱因斯模型，則下列敘述何者正確？","options":["家戶單位的消費與儲蓄都會增加","家戶單位的消費與儲蓄均為正數","家戶單位的平均消費傾向與平均儲蓄傾向都會增加","家戶單位的邊際消費傾向與邊際儲蓄傾向都會增加"],"answer":"A","official":"(B) 因 S ＝自發性儲蓄 ＋ 誘發性儲蓄，必須誘發性儲\n蓄 自發性儲蓄，儲蓄才會是正數\n(C)  Yd →APC  ，APS \n(D) MPC 與 MPS 不隨著可支配所得的增加而變動"},{"id":"112-5-A-41","exam":"112-5","q":41,"unit":"經濟學","topic":"經濟學","stem":"下列敘述何者錯誤？","options":["近年來，政府數度提高基本工資，表示勞動者的實質工資也隨之增加","工資率是勞動者休閒的代價，是休閒的機會成本","生產要素參與生產後所要求的最低報酬，為生產要素的機會成本","地租是土地的使用價格，地價是土地的買賣價格，兩者呈同向變動"],"answer":"A","official":"(A) 提高基本工資會使名目工資上升，不一定會使實\n質工資增加，因為要考慮物價的變動"},{"id":"112-5-A-42","exam":"112-5","q":42,"unit":"經濟學","topic":"經濟學","stem":"下列敘述何者正確？","options":["勞動供給量為工資率的增函數，因此勞動需求增加，必使個別勞動的工資率上升","土地的供給為垂直線，因此若土地的需求大於供給，則土地需求增加必使地租上升","根據流動性偏好說，貨幣需求量為利率的減函數，因此若貨幣供給增加，必使利率下降","利潤為企業能力的增函數，因此若企業能力提高，必使利潤上升"],"answer":"B","official":"(A) 個別勞動供給曲線可能後彎，因此勞動需求增加\n不一定使個別勞動工資率上升\n(C) 貨幣需求曲線存在流動性陷阱，因此貨幣供給增\n加不一定使利率下降\n(D) 利潤無法以供需法則解釋，且利潤為不確定所\n得，因此企業能力提高不一定使利潤增加","scan":"data:image/webp;base64,"},{"id":"112-5-A-43","exam":"112-5","q":43,"unit":"經濟學","topic":"經濟學","stem":"下列何者會使國內生產毛額(GDP)增加？","options":["張三賣掉家裡閒置多年的老爺車","李四在育嬰留停期滿後重回職場工作","王五退休後領取政府的勞保年金","陳六每年寒暑假都出國血拚"],"answer":"B","official":"(A) 二手商品交易所得不計入 GDP 中\n(C) 勞保年金為移轉收入，不計入 GDP 中\n(D) 本國人在國外的消費不計入 GDP"},{"id":"112-5-A-44","exam":"112-5","q":44,"unit":"經濟學","topic":"經濟學","stem":"假設某國於 2023 年的所得相關統計資料如下：國民所得淨額(NNI)500 億，國內投資淨額 50 億，出口淨額 10 億，間接稅淨額 12 億，國外要素所得淨額 8 億，則下列敘述何者正確？","options":["國內生產毛額(GDP)=508 億", "國民所得毛額(GNI)=510 億", "個人所得(PI)=550 億", "國民所得(NI)=488 億"],"answer":"D","official":"NI ＝ NNI − 間接稅淨額 ＝ 500 − 12 ＝ 488，其餘各項因\n無折舊、勞而不獲、不勞而獲等項目，因此無法計算","scan":"data:image/webp;base64,"},{"id":"112-5-A-45","exam":"112-5","q":45,"unit":"經濟學","topic":"經濟學","stem":"假設某國不考慮政府因素的凱因斯模型為：Y=C+I，C=200+0.8Y，I=50。若充分就業的所得水準為 1500，則下列敘述何者正確？","options":["此一經濟體系發生緊縮缺口 250 億", "若投資增加 250 億，則社會可達充分就業", "若投資增加 250 億，將使社會發生膨脹缺口 1000 億", "在充分就業的所得水準下，儲蓄量為 100 億"],"answer":"D","official":"(A) Y ＝ C ＋ I  Y ＝＋ ＋ 200 0.8Y 50  Y* ＝ 1250 且\nY 1500 f ＝ →存在緊縮缺口\nI\nY K\nI\n ＝ 1\n1b\n＝ −\n1 5\n1 0.8\n＝ ＝ −\n∆Y ＝ 250\nI\nY AD\nK\n  ＝ 250 50\n5 ＝＝\n(B) 社會存在緊縮缺口 50 億，因此投資增加 50 億可\n達充分就業\n(C) ∆I ＝ 250， KI ＝ 5 ∆Y ＝× ＝ 5 250 1250\n＝ ＋ ＝ Y' 1250 1250 2500  1500→發生膨脹缺口\n∆Y ＝ 2500 − 1500 ＝ 1000\nI\nY AD\nK\n  ＝ 1000 200\n5 ＝＝ (膨脹缺口)\n(D) C ＝ 200 0.8Y ＋\n S ＝ −＋ 200 0.2Y ＝ − ＋× 200 0.2 1500 ＝ 100","scan":"data:image/webp;base64,"},{"id":"112-5-A-46","exam":"112-5","q":46,"unit":"經濟學","topic":"經濟學","stem":"有關市場失靈的敘述，下列何者錯誤？","options":["外部成本會造成市場失靈，外部利益並不會造成市場失靈","若公共財由私人提供，會造成市場失靈","若獨占廠商存在規模經濟，形成自然獨占，會造成市場失靈","當交易雙方資訊不對稱時，會造成市場失靈"],"answer":"A","official":"外部性(含外部成本與外部利益)、公共財、自然獨占\n與資訊不對稱，均為造成市場失靈的原因"},{"id":"112-5-A-47","exam":"112-5","q":47,"unit":"經濟學","topic":"經濟學","stem":"下列敘述何者錯誤？","options":["民眾以本國貨幣向銀行買入外幣時的匯率，稱為賣出匯率","將產品以低於國內售價或生產成本的價格銷往他國的行為，稱為傾銷","台積電前往美國、日本等國投資設廠，屬於直接投資","歐盟規定從 2030 年起，銷往歐盟的產品必須符合 ESG(Environmental、Social、Governance)標準，\n屬於獎勵輸出辦法"],"answer":"D","official":"(D) 聯合國於 2004 年提出 ESG 的概念，成為企業經\n營須重視環境永續發展的重要指標。因此歐盟規定\n2030 年起，銷往歐盟的商品必須符合 ESG 標準，表\n示歐盟對進口產品採用更嚴格的檢驗標準，屬於貿易\n行政管制"},{"id":"112-5-A-48","exam":"112-5","q":48,"unit":"經濟學","topic":"經濟學","stem":"聯合新聞網(2023.11.21)：「匯銀主管指出，熱錢連日來湧入臺灣等亞洲新興市場，新臺幣匯率連六天升\n值幅度高達 2.19%，超越臺灣主要貿易對手國貨幣韓元、日圓、人民幣與星元，登上『最強亞幣』寶座。\n展望後市，匯銀主管指出，短期內先看新臺幣匯率 31.5 元關卡是否會被攻破，若升破 31.5 元，匯價將\n進一步挑戰 31.2 元。而昨天新臺幣匯率盤中一度狂升 2.28 角，最多升抵 31.628 元，最後在中央銀行進\n場調節下，升值金額縮至 1.98 角，以 31.658 元報收。」根據上述報導，下列敘述何者正確？","options":["熱錢連日來湧入臺灣，造成外匯需求增加，導致臺幣升值","若匯價由 32.4 升至 31.2，則臺幣升值 3.7%","近期臺幣登上「最強亞幣」寶座，是因為臺幣升值幅度最大","央行可能以賣出外匯的方式進場調節，降低臺幣升值幅度"],"answer":"C","official":"(A) 熱錢湧入臺灣，造成外匯供給增加，導致臺幣升值\n(B) 臺幣升值幅度\n11\n31.2 32.4 100% 1\n32.4\n−\n＝× 32.4 31.2 100%\n31.2\n− ＝× ≒3.85%\n(D) 若央行欲降低臺幣升值幅度，必須買入外匯"},{"id":"112-5-A-49","exam":"112-5","q":49,"unit":"經濟學","topic":"經濟學","stem":"有關貨幣的相關敘述，下列何者正確？","options":["貨幣總計數M1B 是流量的概念","央行會調整法定準備率和超額準備率來影響貨幣流通數量","股份有限公司發行的股票與公司債，均為資本市場的金融交易工具","中央銀行又稱為政府的銀行，主要功能在促進公營事業民營化"],"answer":"C","official":"(A)  M1B 為存量的概念\n(B) 央行無法調整超額準備率\n(D) 央行的主要功能在執行貨幣政策，與公營事業民\n營化無關"},{"id":"112-5-A-50","exam":"112-5","q":50,"unit":"經濟學","topic":"經濟學","stem":"中央社報導(2022.02.15)：「國際地緣政治重要性日益增加，晶圓代工廠台積電啟動招募具備政治經濟背\n景的博士人才，引發外界高度關注。台積電表示，主要是希望能協助進行市場研究，提供內部政經相關\n情勢的分析與資料。」根據上述報導，有關台積電徵才的敘述，下列何者錯誤？","options":["具備政治經濟背景的博士人才，較為了解國際地緣政治的內涵，此為 know-what","具備政治經濟背景的博士人才，能協助市場研究，此為 know-why","台積電為因應地緣政治日益重要，而招募具備政治經濟背景的博士人才，此為 know-who","台積電招募具備政治經濟背景的博士人才，該博士人才能分析政經相關情事，此為 know-how"],"answer":"B","official":"(B) 具備研究能力為 know-how"}]);
